final class CaptureScreens {
    static void render(ManagerActivity a){switch(a.page){case "capture"->capture(a);case "capture_settings"->settings(a);case "apps"->apps(a);case "inbox"->inbox(a);case "rules"->rules(a);default->diagnostics(a);}}
    private static void capture(ManagerActivity a){View v=a.original("自动记账","activity_auto");Ui.hide(v,"auto_notify_layout","log_mode","screenshot_tip","delete_screenshot_layout");
        bind(v,"switch_auto_bill",AutoApps.enabled(),value->{AutoApps.enable(value);if(value){if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},6300);JSONObject state=ReferenceCaptureService.status();if(!state.optBoolean("permissionGranted"))a.startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}a.reload();});
        bind(v,"switch_overlays",ReferenceApplication.prefs().getBoolean("show_overlay",true),value->ReferenceApplication.prefs().edit().putBoolean("show_overlay",value).apply());
        bind(v,"switch_auto_jump_accessibility",ReferenceApplication.prefs().getBoolean("accessibility_shortcut",false),value->ReferenceApplication.prefs().edit().putBoolean("accessibility_shortcut",value).apply());
        View screenshot=Ui.view(v,"switch_screenshot");if(screenshot instanceof CompoundButton button){button.setChecked(false);button.setOnCheckedChangeListener((b,on)->{if(on){button.setChecked(false);Ui.offline(a);}});}
        JSONObject status=ReferenceCaptureService.status();JSONObject meta=status.optJSONObject("diagnostics");String condition=!AutoApps.enabled()?"自动记账开关已关闭":AutoApps.selected().isEmpty()?"尚未选择支持的应用":!status.optBoolean("permissionGranted")?"尚未获得无障碍权限":!status.optBoolean("connected")?"已授权，服务尚未连接":"无障碍服务已连接";
        Ui.text(v,"auto_tip",condition+"\n原版规则采集，生成本地待确认账单。\n最近状态："+result(meta.optString("result"))+"\n点击查看诊断或重新授权。");Ui.click(v,"text_tip_layout",()->a.open("diagnostics",0));Ui.click(v,"auto_guide",()->a.open("help",0));Ui.click(v,"not_work_layout",()->a.open("diagnostics",0));Ui.click(v,"allow_run_back",()->a.startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.getPackageName()))));Ui.click(v,"auto_setting_layout",()->a.open("capture_settings",0));Ui.click(v,"notify_setting_layout",()->{if(Build.VERSION.SDK_INT>=26)a.startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,a.getPackageName()));});Ui.click(v,"app_setting_layout",()->a.open("apps",0));Ui.click(v,"auto_manager",()->a.open("rules",0));Ui.click(v,"auto_bill",()->a.open("inbox",0));Ui.click(v,"send_log",()->copy(a));Ui.text(v,"send_log","复制诊断信息");Ui.click(v,"delete_log",()->{ReferenceDiagnostics.clear();a.reload();});Ui.text(v,"delete_log","清空诊断计数");}
    static void bind(View root,String id,boolean checked,java.util.function.Consumer<Boolean> callback){View v=Ui.view(root,id);if(v instanceof CompoundButton button){button.setOnCheckedChangeListener(null);button.setChecked(checked);button.setOnCheckedChangeListener((b,value)->callback.accept(value));}}
    private static void settings(ManagerActivity a){View v=a.original("自动记账设置","activity_auto_setting");Ui.text(v,"default_asset",accountName(a,ReferenceApplication.prefs().getLong("default_account",0)));Ui.click(v,"default_asset_layout",()->accounts(a,id->{ReferenceApplication.prefs().edit().putLong("default_account",id).apply();a.reload();}));bind(v,"switch_add_remark",ReferenceApplication.prefs().getBoolean("add_remark",true),on->ReferenceApplication.prefs().edit().putBoolean("add_remark",on).apply());autoSaveSwitch(a,v);bind(v,"switch_choice_book",true,on->{chooseBook(a);});bind(v,"switch_close_total",ReferenceApplication.prefs().getBoolean("capture_not_total",false),on->ReferenceApplication.prefs().edit().putBoolean("capture_not_total",on).apply());bind(v,"switch_close_budget",ReferenceApplication.prefs().getBoolean("capture_not_budget",false),on->ReferenceApplication.prefs().edit().putBoolean("capture_not_budget",on).apply());bind(v,"switch_repeat_check",true,on->{Ui.toast(a,"实验对比分支保留原版1秒/10秒去重规则");a.reload();});Ui.text(v,"window_style","详细");Ui.click(v,"window_style_layout",()->Ui.toast(a,"使用一木原版详细浮窗布局"));Ui.click(v,"choice_shop_layout",()->a.open("rules",0));Ui.click(v,"choice_book_layout",()->chooseBook(a));}
    private static void autoSaveSwitch(ManagerActivity a,View view){bind(view,"switch_auto_add",ReferenceApplication.prefs().getBoolean("auto_save",false),on->{if(!on){ReferenceApplication.prefs().edit().putBoolean("auto_save",false).apply();return;}bind(view,"switch_auto_add",false,ignored->{});AlertDialog dialog=new AlertDialog.Builder(a).setTitle("启用自动保存").setMessage("识别结果会直接保存。建议先核对当前支付客户端的金额和收支方向。").setNegativeButton("取消",null).setPositiveButton("启用",(d,w)->ReferenceApplication.prefs().edit().putBoolean("auto_save",true).apply()).create();dialog.setOnDismissListener(d->{if(!a.isFinishing())a.reload();});dialog.show();});}
    private static void chooseBook(ManagerActivity a){List<JSONObject> books=new ArrayList<>();for(JSONObject b:a.store().books())if(b.optString("currency").equals("CNY"))books.add(b);if(books.isEmpty()){Ui.toast(a,"请先建立人民币账本");return;}String[] names=new String[books.size()];for(int i=0;i<names.length;i++)names[i]=books.get(i).optString("name");new AlertDialog.Builder(a).setTitle("采集目标账本").setItems(names,(d,w)->{ReferenceApplication.prefs().edit().putLong("capture_book",books.get(w).optLong("id")).apply();a.reload();}).show();}
    interface AccountResult{void value(long id);}
    static void accounts(ManagerActivity a,AccountResult callback){List<JSONObject> accounts=a.store().query("SELECT * FROM accounts WHERE archived=0 AND currency='CNY' ORDER BY id");String[] names=new String[accounts.size()+1];names[0]="无账户";for(int i=0;i<accounts.size();i++)names[i+1]=accounts.get(i).optString("name")+" · "+accounts.get(i).optString("currency");new AlertDialog.Builder(a).setTitle("选择账户").setItems(names,(d,w)->callback.value(w==0?0:accounts.get(w-1).optLong("id"))).show();}
    private static String accountName(ManagerActivity a,long id){JSONObject row=a.store().one("SELECT name FROM accounts WHERE id=?",""+id);return row==null?"无账户":row.optString("name");}
    private static void apps(ManagerActivity a){View v=a.original("配置支持的应用","activity_auto_app_setting");RecyclerView list=Ui.view(v,"app_list");list.setLayoutManager(new LinearLayoutManager(a));list.setAdapter(new RecyclerView.Adapter<MainActivity.SimpleHolder>(){@Override public int getItemCount(){return AutoApps.ALL.length;}@Override public MainActivity.SimpleHolder onCreateViewHolder(ViewGroup p,int type){LinearLayout row=Ui.row(a,"","",null);Switch toggle=new Switch(a);row.addView(toggle);return new MainActivity.SimpleHolder(row);}@Override public void onBindViewHolder(MainActivity.SimpleHolder h,int position){AutoApps.App app=AutoApps.ALL[position];LinearLayout row=(LinearLayout)h.itemView;((TextView)row.getChildAt(0)).setText(app.name);((TextView)row.getChildAt(1)).setText(app.description+"\n"+app.packageName);Switch toggle=(Switch)row.getChildAt(2);toggle.setContentDescription(app.name+"采集开关");toggle.setOnCheckedChangeListener(null);toggle.setChecked(AutoApps.selected().contains(app.packageName));toggle.setOnCheckedChangeListener((b,on)->AutoApps.select(app.packageName,on));row.setOnLongClickListener(view->{List<JSONObject> tags=a.store().query("SELECT * FROM tags ORDER BY id");String[] labels=new String[tags.size()+1];labels[0]="不自动添加标签";for(int i=0;i<tags.size();i++)labels[i+1]=tags.get(i).optString("name");new AlertDialog.Builder(a).setTitle(app.name+"来源标签").setItems(labels,(d,w)->ReferenceApplication.prefs().edit().putString("source_tag_"+app.packageName,w==0?"":""+tags.get(w-1).optLong("id")).apply()).show();return true;});}});}
    private static void inbox(ManagerActivity a){View v=a.original("自动记账待确认","activity_auto_bill");Ui.hide(v,"edit_layout");List<JSONObject> rows=a.store().candidates();Ui.show(v,"no_data_layout",rows.isEmpty());RecyclerView list=Ui.view(v,"bill_list");list.setLayoutManager(new LinearLayoutManager(a));list.setAdapter(new RecyclerView.Adapter<MainActivity.SimpleHolder>(){@Override public int getItemCount(){return rows.size();}@Override public MainActivity.SimpleHolder onCreateViewHolder(ViewGroup p,int t){return new MainActivity.SimpleHolder(Ui.row(a,"","",null));}@Override public void onBindViewHolder(MainActivity.SimpleHolder h,int index){JSONObject row=rows.get(index),data=Json.parse(row.optString("payload"));LinearLayout v=(LinearLayout)h.itemView;String c=data.optString("currency","CNY");((TextView)v.getChildAt(0)).setText(data.optString("origin","采集")+" · "+Money.text(data.optLong("amount"),c));((TextView)v.getChildAt(1)).setText(data.optString("merchant")+"\n"+data.optString("remark")+" · "+Ui.date(row.optLong("created"),"MM.dd HH:mm")+(data.optLong("amount")==0?"\n金额缺失，请手动核对":""));v.setOnClickListener(x->Ui.edit(a,0,row.optString("id")));v.setOnLongClickListener(x->{Ui.confirm(a,"忽略此记录","此记录不会进入账本。",()->{a.store().dismiss(row.optString("id"));YimuKernel.complete(row.optString("id"));CaptureNotifications.update();a.reload();});return true;});}});}
    private static void rules(ManagerActivity a){a.body("自动修正管理",null,null);a.rows.addView(Ui.row(a,"商户沿用规则","在账单编辑的配置中开启“记住此商户”，后续会沿用所选分类和账户。",null));for(JSONObject rule:a.store().query("SELECT r.*,c.name category,a.name account FROM rules r LEFT JOIN categories c ON c.id=r.category_id LEFT JOIN accounts a ON a.id=r.account_id ORDER BY r.id"))a.rows.addView(Ui.row(a,rule.optString("merchant"),rule.optString("category")+" · "+rule.optString("account","无账户"),()->Ui.confirm(a,"删除修正规则",rule.optString("merchant"),()->{a.store().deleteSimple("rules",rule.optLong("id"));a.reload();})));}
    private static void diagnostics(ManagerActivity a){a.body("自动记账诊断","刷新",a::reload);JSONObject status=ReferenceCaptureService.status(),meta=status.optJSONObject("diagnostics");a.rows.addView(Ui.row(a,"当前状态",result(meta.optString("result")),null));a.rows.addView(Ui.row(a,"授权与连接","开关："+status.optBoolean("enabled")+"\n无障碍授权："+status.optBoolean("permissionGranted")+"\n服务连接："+status.optBoolean("connected"),()->a.startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))));long target=ReferenceApplication.prefs().getLong("capture_book",1);JSONObject book=a.store().book(target);a.rows.addView(Ui.row(a,"采集目标账本",book==null?"不存在":book.optString("name")+" · "+book.optString("currency"),()->chooseBook(a)));a.rows.addView(Ui.row(a,"所选应用与实际监听","已选 "+AutoApps.selected().size()+" 个\n实际包名："+status.optJSONArray("effectivePackages")+"\nflags="+status.optInt("flags")+"，eventTypes="+status.optInt("eventTypes"),()->a.open("apps",0)));a.rows.addView(Ui.row(a,"本次运行计数","事件 "+meta.optLong("events")+" · 读取 "+meta.optLong("reads")+" · 处理器提交 "+meta.optLong("submissionAttempts")+" · 草稿 "+meta.optLong("drafts")+"\n队列跳过 "+meta.optLong("skipped"),null));a.rows.addView(Ui.row(a,"最近事件",meta.optString("package")+"\n"+meta.optString("pageClass")+"\n"+(meta.optLong("lastEventAt")>0?Ui.date(meta.optLong("lastEventAt"),"MM.dd HH:mm:ss"):"暂无事件"),null));a.rows.addView(Ui.row(a,"最近异常（保留至手动清空）",meta.optLong("failures")==0?"暂无异常":meta.optLong("failures")+" 次 · "+meta.optString("lastFailureCode")+"\n"+meta.optString("lastFailureType")+"\n"+Ui.date(meta.optLong("lastFailureAt"),"MM.dd HH:mm:ss"),null));a.rows.addView(Ui.row(a,"最近原版遍历","文字项 "+meta.optInt("textCount")+" · 遍历分支 "+meta.optInt("visitedBranches"),null));Switch source=new Switch(a);source.setText("对比读取活动窗口（默认使用一木原版事件来源）");source.setChecked(ReferenceApplication.prefs().getBoolean("use_active_window",false));source.setOnCheckedChangeListener((b,on)->ReferenceApplication.prefs().edit().putBoolean("use_active_window",on).apply());a.rows.addView(source);a.rows.addView(Ui.row(a,"复制诊断信息","只复制开关、包名、页面类、时间、计数与结果码。",()->copy(a)));a.rows.addView(Ui.row(a,"打开待确认列表","已有 "+a.store().candidates().size()+" 条记录",()->a.open("inbox",0)));}
    private static void copy(ManagerActivity a){JSONObject status=ReferenceCaptureService.status();((ClipboardManager)a.getSystemService(android.content.Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("自动记账诊断",status.toString()));Ui.toast(a,"已复制诊断信息");}
    private static String result(String value){return switch(value){case "NO_EVENT"->"尚未收到所选应用的事件";case "CONNECTED"->"服务已连接，等待交易页面";case "EVENT_RECEIVED"->"收到页面事件，等待处理";case "SOURCE_UNAVAILABLE"->"事件未提供可用页面节点";case "EMPTY_TREE"->"原版遍历未读取到文字";case "PAGE_GATE_NOT_MATCHED"->"未进入原版处理器支持的页面状态";case "NO_BILL_FROM_ORIGINAL_RULES"->"原版规则未提交账单，请核对页面与客户端版本";case "DRAFT_SAVED"->"已生成待确认账单";case "AUTO_SAVED"->"已自动保存账单";case "ORIGINAL_REPEAT_GATE"->"被原版1秒/10秒去重拦截";case "TARGET_BOOK_UNAVAILABLE"->"目标人民币账本不存在或不可用";case "QUEUE_FULL"->"采集队列拥堵，有页面事件被跳过";case "PROCESSING_FAILED"->"原版采集处理发生异常";case "STORE_FAILED","PLAN_STORE_FAILED"->"本地保存失败，请核对待确认列表";case "OVERLAY_UNAVAILABLE"->"浮窗未显示，账单仍在待确认列表";case "DISCONNECTED"->"服务已断开，请重新开启无障碍服务";default->value;};}
}
